     'Geometric angle. Codes: DD (degree), RAD (radian), D61 (minute of arc).',
     170),

    -- ── Count and dimensionless ───────────────────────────────────────────────
    ('quantity', 'Quantity / Count',
     'shared.uom_quantity_type',
     'Dimensionless discrete count. Codes: C62 (one), EA (each), PR, DZN, GRO, SET, PK, BX, CT, CS, PL, RL, SH, BA.',
     180),
    ('ratio', 'Ratio / Dimensionless',
     'shared.uom_quantity_type',
     'Pure ratio with no physical dimension. Codes: P1 (%), C62 (one), GK (g/kg).',
     190),

    -- ── Digital / data ────────────────────────────────────────────────────────
    ('digital', 'Digital Data',
     'shared.uom_quantity_type',
     'Information quantity. Codes: E68 (bit), AD (byte), E36 (KB), 4L (MB), E34 (GB), E35 (TB).',
     200),

    -- ── Financial ─────────────────────────────────────────────────────────────
    ('currency', 'Currency / Monetary',
     'shared.uom_quantity_type',
     'Monetary amount. UoM code = ISO 4217 currency code (e.g. MYR, USD, EUR). FK: shared.currency.',
     210),

    -- ── Service / Labour / IT ─────────────────────────────────────────────────
    -- REQUIRED: used by shared.uom entries for labour, subscription, logistics,
    -- and IT service billing units. Must be present before uom seed runs.
    ('service', 'Service / Labour / IT',
     'shared.uom_quantity_type',
     'Work-based, subscription, and IT service units. Codes: MHR (man-hour), DAD (man-day), FTE, LS (lump sum), E48 (user), E49 (seat), E50 (licence), E51 (transaction), E52 (API call), SPR (sprint), STP (story point), E99 (trip), E91 (shipment), TNK (tonne-km).',
     220)

) AS v(code, name, domain_code, description, sort_order)
WHERE NOT EXISTS (
    SELECT 1 FROM control.lookup_value x
    WHERE x.domain_code = v.domain_code AND x.code = v.code AND x.tenant_id IS NULL
);


-- ------------------------------------------------------------
-- FILE: 010_system/000_public/000_bootstrap.sql
-- ------------------------------------------------------------

-- 900_seed_data/000_public/000_bootstrap.sql
-- Bootstrap: system tenant + system principal (self-referential)
-- Must execute FIRST — before all other seeds.
-- Uses session_replication_role = replica to bypass FK/CHECK triggers during bootstrap.

BEGIN;

SET LOCAL session_replication_role = replica;

-- §1  System Tenant — well-known UUID, required by principal FK
INSERT INTO master.tenant (
    id, code, name, display_name, realm_key, region, subscription,
    status, created_by
)
VALUES (
    '00000000-0000-0000-0000-000000000000'::uuid,
    'system',
    'System Tenant',
    'System',
    'athyper',
    NULL,
    'base',
    'active',
    '00000000-0000-0000-0000-000000000000'::uuid   -- self-ref bootstrap
)
ON CONFLICT (id) DO NOTHING;

-- §2  System Principal — self-referential created_by
INSERT INTO master.principal (
    id, tenant_id, code, name, principal_type,
    is_service_account,
    status, created_by
)
VALUES (
    '00000000-0000-0000-0000-000000000000'::uuid,
    '00000000-0000-0000-0000-000000000000'::uuid,   -- system tenant
    'systemadmin',
    'System Administrator',
    'SYSTEM',
    true,
    'active',
    '00000000-0000-0000-0000-000000000000'::uuid    -- self-referential bootstrap
)
ON CONFLICT (id) DO NOTHING;

COMMIT;
-- session_replication_role resets automatically at transaction end (SET LOCAL).


