    CASE WHEN data_type = 'enum' THEN '{}'::jsonb END
FROM (VALUES
            (v_ev,'title',              'title',              'Title',          'string', 'text',     'one','standard',true, false, true,  true, 110,v_su),
            (v_ev,'kind',               'kind',               'Kind',           'enum',   'select',   'one','standard',true, true,  true,  false,120,v_su),
