    -- ── ESG & Environmental ──────────────────────────────────────────────
    ('SC-ENV-WASTE',     'BI-OPEX-ENV'),
    ('SC-ENV-CARBON',    'BI-OPEX-ENV'),
    ('SC-ENV-REMEDN',    'BI-REG-ENV'),

    -- ── Outsourced & Shared Services ─────────────────────────────────────
