    ('GRP-A-ROU',  'Right-of-Use Assets',        'GRP-A', 2, 'asset', 'header', 'debit', 1750),
    ('GRP-A-ICR',  'Intercompany Receivables',   'GRP-A', 2, 'asset', 'header', 'debit', 1800);

    -- B2: L2 HEADERS — Liabilities
