    ('GRP-A-FA-CWIP',    'Capital Work in Progress',        'GRP-A-FA',   3, 'asset', 'posting', 'debit',  NULL,         1570),
    -- Accumulated Depreciation
    ('GRP-A-DEP-BLDG',   'Accum Depr — Buildings',         'GRP-A-DEP',  3, 'contra_asset', 'posting', 'credit', NULL,         1620),
