    ('AJED', 'EXT', 'TUITION',  'Tuition Fees',             'revenue',    10),
    ('AJED', 'EXT', 'RESEARCH', 'Research Grants',          'revenue',    20),
    ('AJED', 'SVC', 'EXEC',     'Executive Education',       'service',   10),
