    -- ── ASPE — South Africa Crude Petroleum (4 warehouses) ──────────────
    INSERT INTO tmp_wh (company_code, site_code, code, name, description, warehouse_type) VALUES
    ('ASPE', 'ASPE-SITE-FIELD-01', 'WH-SPARES',
     'Field Spares',
