    ('TJ-SA', 'SA-VAT',       'SALE',     'zero',        0.00, 'NONE', NULL, 'NONE', 11),
    ('TJ-SA', 'SA-WHT',       'SALE',     'standard',    5.00, 'NONE', NULL, 'NONE', 10),
    ('TJ-SA', 'SA-WHT',       'SALE',     'management', 20.00, 'NONE', NULL, 'NONE', 11),
    ('TJ-SA', 'SA-ZAKAT',     'SALE',     NULL,          2.50, 'NONE', NULL, 'NONE', 10),

    -- ─── UAE (VAT recoverable) ──────────────────────────────────────────
