    ('TJ-AE', 'AE-VAT',       'PURCHASE', NULL,          5.00, 'FULL', NULL, 'NONE', 10),
    ('TJ-AE', 'AE-VAT',       'SALE',     'zero',        0.00, 'NONE', NULL, 'NONE', 11),

