    VALUES
    -- ─── MALAYSIA (SST — not recoverable, sale only) ────────────────────
    (v_tid, 'TG-MY-SST-SALES-10','MY SST Sales 10%',    'Sales tax on goods',     false,'active',v_su,v_meta),
