    (v_tid, 'TG-SA-VAT-15-IN',    'SA VAT 15% Input',    'Purchase VAT 15% recovery',false,'active',v_su,v_meta),
    (v_tid, 'TG-SA-VAT-ZERO',     'SA VAT Zero-rated',   'Zero-rated exports',     false,'active',v_su,v_zero),
